/* ---------------- Design tokens ---------------- */
const C = {
  navy: "#16243F", navyLight: "#233860", gold: "#C6A15B", goldSoft: "#E9D9B4",
  mist: "#EEF1F7", card: "#FFFFFF", ink: "#1B2434", subtext: "#6B7385",
  sage: "#3F7A5C", sageSoft: "#E4F1EA", ember: "#B3492F", emberSoft: "#F7E6E1",
  amber: "#B7862F", amberSoft: "#F5EBD8", line: "#E3E7EF",
};
const AVATAR_PALETTE = ["#8A9BC4", "#C6A15B", "#7FA98F", "#C08A6B", "#A98FB0", "#6FA2A6"];

const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const fmtDate = (iso) => { if (!iso) return "—"; const d = new Date(iso); return d.toLocaleDateString("ar-EG", { year: "numeric", month: "long", day: "numeric" }); };
const fmtDateShort = (iso) => { if (!iso) return "—"; const d = new Date(iso); return d.toLocaleDateString("ar-EG", { year: "numeric", month: "2-digit", day: "2-digit" }); };

function initials(name) {
  const parts = (name || "").trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return "؟";
  if (parts.length === 1) return parts[0].slice(0, 1);
  return parts[0].slice(0, 1) + parts[1].slice(0, 1);
}
function avatarColor(name) {
  const s = (name || "").split("").reduce((a, c) => a + c.charCodeAt(0), 0);
  return AVATAR_PALETTE[s % AVATAR_PALETTE.length];
}
// بيرجع صورة مضغوطة كنص base64 صغير عشان نخزنها مباشرة جوه مستند Firestore
// (بدون الحاجة لخدمة Storage المنفصلة اللي بقت تتطلب حساب فوترة)
function compressImage(file, maxDim = 320, quality = 0.6) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("تعذرت قراءة الملف"));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("تعذر تحميل الصورة"));
      img.onload = () => {
        let { width, height } = img;
        if (width > height && width > maxDim) { height = Math.round((height * maxDim) / width); width = maxDim; }
        else if (height > maxDim) { width = Math.round((width * maxDim) / height); height = maxDim; }
        const canvas = document.createElement("canvas");
        canvas.width = width; canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

/* ---------------- UI primitives ---------------- */

function Avatar({ name, photo, size = 44 }) {
  if (photo) {
    return <img src={photo} alt={name} style={{ width: size, height: size, borderRadius: "999px", objectFit: "cover", flexShrink: 0, border: `2px solid ${C.line}` }} />;
  }
  return (
    <div style={{ width: size, height: size, borderRadius: "999px", flexShrink: 0, background: avatarColor(name), color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, fontSize: size * 0.36 }}>
      {initials(name)}
    </div>
  );
}

function Badge({ status }) {
  const map = {
    present: { label: "حاضر", bg: C.sageSoft, fg: C.sage, Icon: CheckCircle2 },
    absent: { label: "غائب", bg: C.emberSoft, fg: C.ember, Icon: XCircle },
    excused: { label: "غائب بعذر", bg: C.amberSoft, fg: C.amber, Icon: Clock3 },
    none: { label: "لم يُسجَّل", bg: C.mist, fg: C.subtext, Icon: Clock3 },
  };
  const s = map[status] || map.none;
  const { Icon } = s;
  return <span style={{ display: "inline-flex", alignItems: "center", gap: 6, background: s.bg, color: s.fg, padding: "4px 10px", borderRadius: 999, fontSize: 13, fontWeight: 700 }}><Icon size={14} /> {s.label}</span>;
}

function Toasts({ toasts, remove }) {
  return (
    <div style={{ position: "fixed", bottom: 20, left: 20, zIndex: 200, display: "flex", flexDirection: "column", gap: 8 }}>
      {toasts.map((t) => (
        <div key={t.id} onClick={() => remove(t.id)} style={{ cursor: "pointer", background: t.type === "error" ? C.ember : t.type === "warn" ? C.amber : C.navy, color: "#fff", padding: "12px 18px", borderRadius: 10, minWidth: 220, boxShadow: "0 8px 24px rgba(20,30,50,0.25)", fontSize: 14, fontWeight: 600 }}>
          {t.message}
        </div>
      ))}
    </div>
  );
}

function ConfirmDialog({ open, title, message, danger, onConfirm, onCancel, confirmLabel = "تأكيد" }) {
  if (!open) return null;
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(15,20,35,0.5)", zIndex: 300, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }} onClick={onCancel}>
      <div style={{ background: "#fff", borderRadius: 16, padding: 24, maxWidth: 380, width: "100%", boxShadow: "0 20px 50px rgba(0,0,0,0.3)" }} onClick={(e) => e.stopPropagation()}>
        <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
          <div style={{ background: danger ? C.emberSoft : C.mist, color: danger ? C.ember : C.navy, borderRadius: 999, padding: 10, flexShrink: 0 }}><AlertTriangle size={20} /></div>
          <div>
            <div style={{ fontWeight: 800, fontSize: 16, color: C.ink, marginBottom: 4 }}>{title}</div>
            <div style={{ fontSize: 14, color: C.subtext, lineHeight: 1.6 }}>{message}</div>
          </div>
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 20, justifyContent: "flex-end" }}>
          <button onClick={onCancel} style={btnGhost}>إلغاء</button>
          <button onClick={onConfirm} style={danger ? btnDanger : btnPrimary}>{confirmLabel}</button>
        </div>
      </div>
    </div>
  );
}

function Modal({ open, onClose, title, children, width = 520 }) {
  if (!open) return null;
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(15,20,35,0.5)", zIndex: 250, display: "flex", alignItems: "flex-start", justifyContent: "center", padding: 16, overflowY: "auto" }} onClick={onClose}>
      <div style={{ background: "#fff", borderRadius: 18, maxWidth: width, width: "100%", marginTop: 40, marginBottom: 40, boxShadow: "0 24px 60px rgba(0,0,0,0.32)" }} onClick={(e) => e.stopPropagation()}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "18px 22px", borderBottom: `1px solid ${C.line}` }}>
          <div style={{ fontWeight: 800, fontSize: 17, color: C.ink }}>{title}</div>
          <button onClick={onClose} style={{ background: C.mist, border: "none", borderRadius: 999, width: 32, height: 32, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: C.subtext }}><X size={16} /></button>
        </div>
        <div style={{ padding: 22 }}>{children}</div>
      </div>
    </div>
  );
}

