/* ---------------- Auth screens ---------------- */

function AuthScreen({ mode, setMode, onLogin, onSignup, toast }) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [busy, setBusy] = useState(false);

  const submit = async (e) => {
    e.preventDefault();
    if (!email.trim() || !password.trim() || (mode === "signup" && !name.trim())) {
      toast("من فضلك املأ كل الحقول", "error");
      return;
    }
    setBusy(true);
    try {
      if (mode === "login") await onLogin(email.trim(), password);
      else await onSignup(email.trim(), password, name.trim());
    } catch (err) {
      toast(friendlyAuthError(err), "error");
    }
    setBusy(false);
  };

  return (
    <div style={{ minHeight: "100vh", background: `linear-gradient(180deg, ${C.navy}, #0F1930)`, display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
      <div style={{ background: "#fff", borderRadius: 22, width: "100%", maxWidth: 380, boxShadow: "0 30px 70px rgba(0,0,0,0.4)", overflow: "hidden" }}>
        <div style={{ background: `linear-gradient(160deg, ${C.navy}, ${C.navyLight})`, padding: "32px 24px 24px", textAlign: "center" }}>
          <img src={LOGO_SRC} alt="أسرة البابا كيرلس" style={{ width: 110, borderRadius: 14, boxShadow: "0 10px 24px rgba(0,0,0,0.35)" }} />
          <div style={{ color: "#fff", fontWeight: 800, fontSize: 19, marginTop: 16 }}>أسرة البابا كيرلس</div>
          <div style={{ color: C.goldSoft, fontSize: 14, marginTop: 2 }}>خامسة ابتدائي — نظام الحضور والغياب</div>
        </div>
        <form onSubmit={submit} style={{ padding: 26 }}>
          {mode === "signup" && (
            <Field label="الاسم" required><input style={inputStyle} value={name} onChange={(e) => setName(e.target.value)} autoFocus /></Field>
          )}
          <Field label="البريد الإلكتروني" required><input style={inputStyle} type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="name@example.com" /></Field>
          <Field label="كلمة المرور" required>
            <div style={{ position: "relative" }}>
              <input style={{ ...inputStyle, paddingLeft: 40 }} type={showPw ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="6 حروف على الأقل" />
              <button type="button" onClick={() => setShowPw((s) => !s)} style={{ position: "absolute", left: 8, top: 8, background: "none", border: "none", color: C.subtext, cursor: "pointer" }}>{showPw ? <EyeOff size={18} /> : <Eye size={18} />}</button>
            </div>
          </Field>
          <button type="submit" disabled={busy} style={{ ...btnGold, width: "100%", justifyContent: "center", padding: "12px 18px", marginTop: 6 }}>
            {busy ? "جارٍ التنفيذ..." : mode === "login" ? "تسجيل الدخول" : "إنشاء حساب"}
          </button>
          <div style={{ textAlign: "center", marginTop: 16, fontSize: 13, color: C.subtext }}>
            {mode === "login" ? (
              <>مفيش حساب؟ <button type="button" onClick={() => setMode("signup")} style={{ background: "none", border: "none", color: C.navy, fontWeight: 800, cursor: "pointer" }}>سجّل حساب جديد</button></>
            ) : (
              <>عندك حساب بالفعل؟ <button type="button" onClick={() => setMode("login")} style={{ background: "none", border: "none", color: C.navy, fontWeight: 800, cursor: "pointer" }}>سجّل الدخول</button></>
            )}
          </div>
          {mode === "signup" && (
            <div style={{ marginTop: 14, background: C.mist, borderRadius: 10, padding: "10px 12px", fontSize: 12.5, color: C.subtext, lineHeight: 1.7 }}>
              أول شخص يسجّل حساب في النظام بيبقى "مسؤول" تلقائيًا، وأي حد بعده بيبقى "خادم" لحد ما المسؤول يرفّعه.
            </div>
          )}
        </form>
      </div>
    </div>
  );
}

function friendlyAuthError(err) {
  const code = err?.code || "";
  if (code.includes("email-already-in-use")) return "البريد الإلكتروني ده مستخدم بالفعل";
  if (code.includes("invalid-credential") || code.includes("wrong-password") || code.includes("user-not-found")) return "البريد الإلكتروني أو كلمة المرور غير صحيحة";
  if (code.includes("weak-password")) return "كلمة المرور لازم تكون 6 حروف على الأقل";
  if (code.includes("invalid-email")) return "صيغة البريد الإلكتروني غير صحيحة";
  return "حدث خطأ، حاول مرة أخرى";
}

