/* ---------------- Dashboard ---------------- */

function Dashboard({ members, meetings, attendance, setView, setViewParams }) {
  const lastMeeting = useMemo(() => [...meetings].sort((a, b) => new Date(b.date) - new Date(a.date))[0], [meetings]);
  const lastStats = useMemo(() => {
    if (!lastMeeting) return { present: 0, absent: 0 };
    const recs = attendance.filter((a) => a.meetingId === lastMeeting.id);
    return { present: recs.filter((r) => r.status === "present").length, absent: recs.filter((r) => r.status === "absent").length };
  }, [lastMeeting, attendance]);
  const overallRate = useMemo(() => {
    const present = attendance.filter((a) => a.status === "present").length;
    return attendance.length ? Math.round((present / attendance.length) * 100) : 0;
  }, [attendance]);
  const recentMeetings = useMemo(() => [...meetings].sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 5), [meetings]);

  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(190px, 1fr))", gap: 16, marginBottom: 24 }}>
        <StatCard label="عدد المخدومين" value={members.length} icon={Users} accent={C.navy} />
        <StatCard label="عدد الاجتماعات" value={meetings.length} icon={Calendar} accent={C.gold} />
        <StatCard label="حضور آخر اجتماع" value={lastStats.present} icon={CheckCircle2} accent={C.sage} />
        <StatCard label="غياب آخر اجتماع" value={lastStats.absent} icon={XCircle} accent={C.ember} />
        <StatCard label="نسبة الحضور العامة" value={overallRate + "%"} icon={TrendingUp} accent={C.amber} />
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1.4fr 1fr", gap: 18 }} className="dash-grid">
        <div style={{ background: C.card, borderRadius: 16, padding: 20, boxShadow: "0 2px 10px rgba(20,30,50,0.05)" }}>
          <div style={{ fontWeight: 800, fontSize: 15.5, marginBottom: 14, color: C.ink }}>أحدث الاجتماعات</div>
          {recentMeetings.length === 0 ? <div style={{ color: C.subtext, fontSize: 14, padding: "20px 0", textAlign: "center" }}>لا توجد اجتماعات بعد</div> : recentMeetings.map((m) => (
            <button key={m.id} onClick={() => { setViewParams({ meetingId: m.id }); setView("attendance"); }} style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 4px", background: "none", border: "none", borderBottom: `1px solid ${C.line}`, cursor: "pointer", textAlign: "right" }}>
              <div>
                <div style={{ fontWeight: 700, fontSize: 14, color: C.ink }}>{m.title || "اجتماع"}</div>
                <div style={{ fontSize: 12.5, color: C.subtext, marginTop: 2 }}>{fmtDate(m.date)}</div>
              </div>
              <ChevronLeft size={18} color={C.subtext} />
            </button>
          ))}
        </div>
        <div style={{ background: C.card, borderRadius: 16, padding: 20, boxShadow: "0 2px 10px rgba(20,30,50,0.05)" }}>
          <div style={{ fontWeight: 800, fontSize: 15.5, marginBottom: 14, color: C.ink }}>إجراءات سريعة</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
            <button onClick={() => { setViewParams({ openAdd: true }); setView("members"); }} style={{ ...btnGhost, justifyContent: "flex-start", width: "100%" }}><UserPlus size={17} /> إضافة مخدوم جديد</button>
            <button onClick={() => { setViewParams({ openAdd: true }); setView("meetings"); }} style={{ ...btnGhost, justifyContent: "flex-start", width: "100%" }}><CalendarPlus size={17} /> إنشاء اجتماع جديد</button>
            <button onClick={() => { setViewParams(lastMeeting ? { meetingId: lastMeeting.id } : {}); setView(lastMeeting ? "attendance" : "meetings"); }} style={{ ...btnGhost, justifyContent: "flex-start", width: "100%" }}><ListChecks size={17} /> تسجيل حضور</button>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------------- Members ---------------- */

function MemberFormModal({ open, onClose, onSave, initial, toast }) {
  const blank = { name: "", phone: "", birthDate: "", address: "", fatherName: "", motherName: "", school: "", notes: "", photoURL: null };
  const [form, setForm] = useState(blank);
  const [photoFile, setPhotoFile] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [uploading, setUploading] = useState(false);
  const fileRef = useRef(null);

  useEffect(() => {
    if (open) { setForm(initial ? { ...blank, ...initial } : blank); setPhotoFile(null); setPhotoPreview(null); }
  }, [open, initial]);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const handlePhoto = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (!file.type.startsWith("image/")) { toast("الملف المختار ليس صورة", "error"); return; }
    setUploading(true);
    try {
      const dataUrl = await compressImage(file);
      setPhotoFile(dataUrl);
      setPhotoPreview(dataUrl);
    } catch (err) {
      toast("تعذر معالجة الصورة، حاول مرة أخرى", "error");
    }
    setUploading(false);
  };

  const submit = (e) => {
    e.preventDefault();
    if (!form.name.trim()) { toast("اسم المخدوم مطلوب", "error"); return; }
    onSave(form, photoFile);
  };

  return (
    <Modal open={open} onClose={onClose} title={initial ? "تعديل بيانات المخدوم" : "إضافة مخدوم جديد"} width={560}>
      <form onSubmit={submit}>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 18 }}>
          <div style={{ position: "relative" }}>
            <Avatar name={form.name} photo={photoPreview || form.photoURL} size={84} />
            <button type="button" onClick={() => fileRef.current?.click()} style={{ position: "absolute", bottom: -2, left: -2, background: C.gold, border: "3px solid #fff", borderRadius: 999, width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}><Camera size={14} color={C.navy} /></button>
            <input ref={fileRef} type="file" accept="image/*" onChange={handlePhoto} style={{ display: "none" }} />
          </div>
        </div>
        {uploading && <div style={{ textAlign: "center", fontSize: 12.5, color: C.subtext, marginBottom: 10 }}>جارٍ معالجة الصورة...</div>}
        {(photoPreview || form.photoURL) && (
          <div style={{ textAlign: "center", marginBottom: 10 }}>
            <button type="button" onClick={() => { setPhotoFile(null); setPhotoPreview(null); setForm((f) => ({ ...f, photoURL: null })); }} style={{ background: "none", border: "none", color: C.ember, fontSize: 12.5, cursor: "pointer", fontWeight: 700 }}>إزالة الصورة</button>
          </div>
        )}
        <Field label="الاسم بالكامل" required><input style={inputStyle} value={form.name} onChange={set("name")} placeholder="اسم المخدوم" /></Field>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <Field label="رقم الهاتف"><input style={inputStyle} value={form.phone} onChange={set("phone")} placeholder="01xxxxxxxxx" /></Field>
          <Field label="تاريخ الميلاد"><input style={inputStyle} type="date" value={form.birthDate} onChange={set("birthDate")} /></Field>
        </div>
        <Field label="العنوان"><input style={inputStyle} value={form.address} onChange={set("address")} /></Field>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
          <Field label="اسم الأب"><input style={inputStyle} value={form.fatherName} onChange={set("fatherName")} /></Field>
          <Field label="اسم الأم"><input style={inputStyle} value={form.motherName} onChange={set("motherName")} /></Field>
        </div>
        <Field label="المدرسة"><input style={inputStyle} value={form.school} onChange={set("school")} /></Field>
        <Field label="ملاحظات"><textarea style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} value={form.notes} onChange={set("notes")} /></Field>
        <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", marginTop: 18 }}>
          <button type="button" onClick={onClose} style={btnGhost}>إلغاء</button>
          <button type="submit" style={btnPrimary}><Save size={16} /> حفظ</button>
        </div>
      </form>
    </Modal>
  );
}

function MembersPage({ members, attendance, onAdd, onUpdate, onDelete, openParams, setView, setViewParams, isAdmin, toast, setMobileOpen }) {
  const [search, setSearch] = useState("");
  const [sortBy, setSortBy] = useState("name");
  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  useEffect(() => { if (openParams?.openAdd) { setFormOpen(true); setEditing(null); setViewParams({}); } }, [openParams]);

  const filtered = useMemo(() => {
    let list = members.filter((m) => m.name.includes(search.trim()));
    if (sortBy === "name") list = [...list].sort((a, b) => a.name.localeCompare(b.name, "ar"));
    if (sortBy === "recent") list = [...list].sort((a, b) => (b.createdAtMs || 0) - (a.createdAtMs || 0));
    return list;
  }, [members, search, sortBy]);

  const rateFor = (memberId) => {
    const recs = attendance.filter((a) => a.memberId === memberId);
    const present = recs.filter((r) => r.status === "present").length;
    return recs.length ? Math.round((present / recs.length) * 100) : null;
  };

  return (
    <div>
      <Topbar title="المخدومون" subtitle={`${members.length} مخدوم مسجَّل`} setMobileOpen={setMobileOpen} />
      <div style={{ display: "flex", gap: 10, marginBottom: 18, flexWrap: "wrap" }}>
        <div style={{ position: "relative", flex: 1, minWidth: 220 }}>
          <Search size={16} style={{ position: "absolute", right: 12, top: 12, color: C.subtext }} />
          <input style={{ ...inputStyle, paddingRight: 36 }} placeholder="ابحث بالاسم..." value={search} onChange={(e) => setSearch(e.target.value)} />
        </div>
        <select style={{ ...inputStyle, width: 160 }} value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
          <option value="name">ترتيب: الاسم</option>
          <option value="recent">ترتيب: الأحدث</option>
        </select>
        {isAdmin && <button onClick={() => { setEditing(null); setFormOpen(true); }} style={btnPrimary}><UserPlus size={16} /> إضافة مخدوم</button>}
      </div>

      {filtered.length === 0 ? (
        <EmptyState icon={Users} title={members.length === 0 ? "لا يوجد مخدومون بعد" : "لا توجد نتائج"} subtitle={members.length === 0 ? "ابدأ بإضافة أول مخدوم في الأسرة" : "جرّب كلمة بحث أخرى"} action={isAdmin && members.length === 0 && <button onClick={() => setFormOpen(true)} style={btnPrimary}><UserPlus size={16} /> إضافة مخدوم</button>} />
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(250px, 1fr))", gap: 14 }}>
          {filtered.map((m) => {
            const rate = rateFor(m.id);
            return (
              <div key={m.id} style={{ background: C.card, borderRadius: 16, padding: 16, boxShadow: "0 2px 10px rgba(20,30,50,0.05)" }}>
                <div style={{ display: "flex", gap: 12, alignItems: "center", cursor: "pointer" }} onClick={() => { setViewParams({ memberId: m.id }); setView("memberProfile"); }}>
                  <Avatar name={m.name} photo={m.photoURL} size={52} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 800, fontSize: 15, color: C.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{m.name}</div>
                    <div style={{ fontSize: 12.5, color: C.subtext, marginTop: 2 }}>{m.school || "—"}</div>
                  </div>
                </div>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 14, paddingTop: 12, borderTop: `1px solid ${C.line}` }}>
                  <span style={{ fontSize: 12.5, color: C.subtext, fontWeight: 700 }}>نسبة الحضور: <b style={{ color: rate === null ? C.subtext : rate >= 60 ? C.sage : C.ember }}>{rate === null ? "—" : rate + "%"}</b></span>
                  {isAdmin && (
                    <div style={{ display: "flex", gap: 6 }}>
                      <button onClick={() => { setEditing(m); setFormOpen(true); }} style={{ background: C.mist, border: "none", borderRadius: 8, width: 30, height: 30, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: C.navy }}><Edit2 size={14} /></button>
                      <button onClick={() => setConfirmDelete(m)} style={{ background: C.emberSoft, border: "none", borderRadius: 8, width: 30, height: 30, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: C.ember }}><Trash2 size={14} /></button>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      <MemberFormModal open={formOpen} onClose={() => setFormOpen(false)} initial={editing} toast={toast} onSave={async (data, photoFile) => { if (editing) await onUpdate(editing.id, data, photoFile); else await onAdd(data, photoFile); setFormOpen(false); }} />
      <ConfirmDialog open={!!confirmDelete} title="حذف المخدوم" message={confirmDelete ? `هل تريد حذف "${confirmDelete.name}"؟ سيتم حذف جميع سجلات حضوره أيضًا، ولا يمكن التراجع عن هذا الإجراء.` : ""} danger confirmLabel="حذف نهائيًا" onCancel={() => setConfirmDelete(null)} onConfirm={() => { onDelete(confirmDelete.id); setConfirmDelete(null); }} />
    </div>
  );
}

function MemberProfile({ member, attendance, meetings, setView }) {
  if (!member) return <EmptyState icon={Users} title="لم يتم العثور على المخدوم" subtitle="ربما تم حذفه" action={<button onClick={() => setView("members")} style={btnPrimary}>عودة للمخدومين</button>} />;
  const recs = attendance.filter((a) => a.memberId === member.id).map((a) => ({ ...a, meeting: meetings.find((m) => m.id === a.meetingId) })).filter((a) => a.meeting).sort((a, b) => new Date(b.meeting.date) - new Date(a.meeting.date));
  const present = recs.filter((r) => r.status === "present").length;
  const absent = recs.filter((r) => r.status === "absent").length;
  const excused = recs.filter((r) => r.status === "excused").length;
  const rate = recs.length ? Math.round((present / recs.length) * 100) : 0;

  return (
    <div>
      <button onClick={() => setView("members")} style={{ ...btnGhost, marginBottom: 16 }}><ArrowRight size={16} /> عودة للمخدومين</button>
      <div style={{ background: C.card, borderRadius: 18, padding: 22, boxShadow: "0 2px 10px rgba(20,30,50,0.05)", marginBottom: 18, display: "flex", gap: 18, alignItems: "center", flexWrap: "wrap" }}>
        <Avatar name={member.name} photo={member.photoURL} size={80} />
        <div style={{ flex: 1, minWidth: 200 }}>
          <div style={{ fontSize: 20, fontWeight: 800, color: C.ink }}>{member.name}</div>
          <div style={{ display: "flex", gap: 16, flexWrap: "wrap", marginTop: 8, fontSize: 13, color: C.subtext }}>
            {member.phone && <span style={{ display: "flex", alignItems: "center", gap: 5 }}><Phone size={13} /> {member.phone}</span>}
            {member.school && <span style={{ display: "flex", alignItems: "center", gap: 5 }}><School size={13} /> {member.school}</span>}
            {member.address && <span style={{ display: "flex", alignItems: "center", gap: 5 }}><MapPin size={13} /> {member.address}</span>}
          </div>
          <div style={{ display: "flex", gap: 16, flexWrap: "wrap", marginTop: 8, fontSize: 13, color: C.subtext }}>
            {member.fatherName && <span>اسم الأب: {member.fatherName}</span>}
            {member.motherName && <span>اسم الأم: {member.motherName}</span>}
            {member.birthDate && <span>الميلاد: {fmtDateShort(member.birthDate)}</span>}
          </div>
          {member.notes && <div style={{ marginTop: 8, fontSize: 13, color: C.ink, background: C.mist, padding: "8px 12px", borderRadius: 10 }}>{member.notes}</div>}
        </div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px,1fr))", gap: 14, marginBottom: 18 }}>
        <StatCard label="إجمالي الاجتماعات" value={meetings.length} icon={Calendar} accent={C.navy} />
        <StatCard label="مرات الحضور" value={present} icon={CheckCircle2} accent={C.sage} />
        <StatCard label="مرات الغياب" value={absent} icon={XCircle} accent={C.ember} />
        <StatCard label="غياب بعذر" value={excused} icon={Clock3} accent={C.amber} />
        <StatCard label="نسبة الحضور" value={rate + "%"} icon={TrendingUp} accent={C.gold} />
      </div>
      <div style={{ background: C.card, borderRadius: 16, padding: 20, boxShadow: "0 2px 10px rgba(20,30,50,0.05)" }}>
        <div style={{ fontWeight: 800, fontSize: 15.5, marginBottom: 14, color: C.ink }}>سجل الحضور</div>
        {recs.length === 0 ? <div style={{ color: C.subtext, fontSize: 14, textAlign: "center", padding: "20px 0" }}>لا يوجد سجل حضور بعد</div> : recs.map((r) => (
          <div key={r.id} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "11px 2px", borderBottom: `1px solid ${C.line}` }}>
            <div>
              <div style={{ fontWeight: 700, fontSize: 14, color: C.ink }}>{r.meeting.title || "اجتماع"}</div>
              <div style={{ fontSize: 12.5, color: C.subtext }}>{fmtDate(r.meeting.date)}</div>
            </div>
            <Badge status={r.status} />
          </div>
        ))}
      </div>
    </div>
  );
}

