function MeetingFormModal({ open, onClose, onSave, initial, toast }) {
  const blank = { date: new Date().toISOString().slice(0, 10), title: "", notes: "" };
  const [form, setForm] = useState(blank);
  useEffect(() => { if (open) setForm(initial ? { ...blank, ...initial } : blank); }, [open, initial]);
  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));
  const submit = (e) => { e.preventDefault(); if (!form.date) { toast("تاريخ الاجتماع مطلوب", "error"); return; } onSave(form); };
  return (
    <Modal open={open} onClose={onClose} title={initial ? "تعديل الاجتماع" : "إنشاء اجتماع جديد"} width={460}>
      <form onSubmit={submit}>
        <Field label="تاريخ الاجتماع" required><input style={inputStyle} type="date" value={form.date} onChange={set("date")} /></Field>
        <Field label="عنوان الاجتماع"><input style={inputStyle} value={form.title} onChange={set("title")} placeholder="مثال: اجتماع الأسرة الأسبوعي" /></Field>
        <Field label="ملاحظات"><textarea style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} value={form.notes} onChange={set("notes")} /></Field>
        <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", marginTop: 18 }}>
          <button type="button" onClick={onClose} style={btnGhost}>إلغاء</button>
          <button type="submit" style={btnPrimary}><Save size={16} /> حفظ</button>
        </div>
      </form>
    </Modal>
  );
}

function MeetingsPage({ meetings, attendance, onAdd, onUpdate, onDelete, openParams, setView, setViewParams, isAdmin, toast, setMobileOpen }) {
  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  useEffect(() => { if (openParams?.openAdd) { setFormOpen(true); setEditing(null); setViewParams({}); } }, [openParams]);
  const sorted = useMemo(() => [...meetings].sort((a, b) => new Date(b.date) - new Date(a.date)), [meetings]);
  const statsFor = (meetingId) => {
    const recs = attendance.filter((a) => a.meetingId === meetingId);
    return { present: recs.filter((r) => r.status === "present").length, absent: recs.filter((r) => r.status === "absent").length, excused: recs.filter((r) => r.status === "excused").length };
  };

  return (
    <div>
      <Topbar title="الاجتماعات" subtitle={`${meetings.length} اجتماع`} setMobileOpen={setMobileOpen} />
      {isAdmin && <div style={{ marginBottom: 18 }}><button onClick={() => { setEditing(null); setFormOpen(true); }} style={btnPrimary}><CalendarPlus size={16} /> إنشاء اجتماع جديد</button></div>}
      {sorted.length === 0 ? (
        <EmptyState icon={Calendar} title="لا توجد اجتماعات بعد" subtitle="أنشئ أول اجتماع لتبدأ بتسجيل الحضور" action={isAdmin && <button onClick={() => setFormOpen(true)} style={btnPrimary}><CalendarPlus size={16} /> إنشاء اجتماع</button>} />
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {sorted.map((m) => {
            const s = statsFor(m.id);
            return (
              <div key={m.id} style={{ background: C.card, borderRadius: 14, padding: 16, boxShadow: "0 2px 10px rgba(20,30,50,0.05)", display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
                <div style={{ width: 52, height: 52, borderRadius: 12, background: C.mist, color: C.navy, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <div style={{ fontSize: 17, fontWeight: 800 }}>{new Date(m.date).getDate()}</div>
                  <div style={{ fontSize: 10 }}>{new Date(m.date).toLocaleDateString("ar-EG", { month: "short" })}</div>
                </div>
                <div style={{ flex: 1, minWidth: 160 }}>
                  <div style={{ fontWeight: 800, fontSize: 15, color: C.ink }}>{m.title || "اجتماع"}</div>
                  <div style={{ fontSize: 12.5, color: C.subtext, marginTop: 2 }}>{fmtDate(m.date)}</div>
                </div>
                <div style={{ display: "flex", gap: 8, fontSize: 12.5 }}>
                  <span style={{ color: C.sage, fontWeight: 700 }}>{s.present} حاضر</span>
                  <span style={{ color: C.ember, fontWeight: 700 }}>{s.absent} غائب</span>
                  <span style={{ color: C.amber, fontWeight: 700 }}>{s.excused} بعذر</span>
                </div>
                <div style={{ display: "flex", gap: 8 }}>
                  <button onClick={() => { setViewParams({ meetingId: m.id }); setView("attendance"); }} style={btnGold}><ListChecks size={15} /> تسجيل الحضور</button>
                  {isAdmin && (<>
                    <button onClick={() => { setEditing(m); setFormOpen(true); }} style={{ background: C.mist, border: "none", borderRadius: 8, width: 36, height: 36, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: C.navy }}><Edit2 size={14} /></button>
                    <button onClick={() => setConfirmDelete(m)} style={{ background: C.emberSoft, border: "none", borderRadius: 8, width: 36, height: 36, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", color: C.ember }}><Trash2 size={14} /></button>
                  </>)}
                </div>
              </div>
            );
          })}
        </div>
      )}
      <MeetingFormModal open={formOpen} onClose={() => setFormOpen(false)} initial={editing} toast={toast} onSave={(data) => { if (editing) onUpdate(editing.id, data); else onAdd(data); setFormOpen(false); }} />
      <ConfirmDialog open={!!confirmDelete} title="حذف الاجتماع" message={confirmDelete ? `هل تريد حذف اجتماع "${confirmDelete.title || fmtDate(confirmDelete.date)}"؟ سيتم حذف كل سجلات الحضور الخاصة به.` : ""} danger confirmLabel="حذف نهائيًا" onCancel={() => setConfirmDelete(null)} onConfirm={() => { onDelete(confirmDelete.id); setConfirmDelete(null); }} />
    </div>
  );
}

/* ---------------- Attendance ---------------- */

function AttendancePage({ meeting, members, attendance, currentUser, onSaveAttendance, setView }) {
  const [pending, setPending] = useState({});
  const [search, setSearch] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!meeting) return;
    const map = {};
    attendance.filter((a) => a.meetingId === meeting.id).forEach((a) => { map[a.memberId] = a.status; });
    setPending(map);
  }, [meeting, attendance]);

  if (!meeting) return <EmptyState icon={Calendar} title="اختر اجتماعًا" subtitle="عد إلى صفحة الاجتماعات لاختيار اجتماع لتسجيل الحضور" action={<button onClick={() => setView("meetings")} style={btnPrimary}>عودة للاجتماعات</button>} />;

  const filteredMembers = members.filter((m) => m.name.includes(search.trim()));
  const setStatus = (memberId, status) => setPending((p) => ({ ...p, [memberId]: status }));
  const counts = { present: 0, absent: 0, excused: 0, none: 0 };
  members.forEach((m) => { counts[pending[m.id] || "none"]++; });

  const save = async () => { setSaving(true); await onSaveAttendance(meeting.id, pending, currentUser); setSaving(false); };

  return (
    <div>
      <button onClick={() => setView("meetings")} style={{ ...btnGhost, marginBottom: 16 }}><ArrowRight size={16} /> عودة للاجتماعات</button>
      <div style={{ background: C.card, borderRadius: 16, padding: 18, boxShadow: "0 2px 10px rgba(20,30,50,0.05)", marginBottom: 16, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12 }}>
        <div>
          <div style={{ fontWeight: 800, fontSize: 17, color: C.ink }}>{meeting.title || "اجتماع"}</div>
          <div style={{ fontSize: 13, color: C.subtext, marginTop: 2 }}>{fmtDate(meeting.date)}</div>
        </div>
        <div style={{ display: "flex", gap: 10, fontSize: 12.5, fontWeight: 700 }}>
          <span style={{ color: C.sage }}>{counts.present} حاضر</span>
          <span style={{ color: C.ember }}>{counts.absent} غائب</span>
          <span style={{ color: C.amber }}>{counts.excused} بعذر</span>
          <span style={{ color: C.subtext }}>{counts.none} غير محدد</span>
        </div>
      </div>
      <div style={{ position: "relative", marginBottom: 14 }}>
        <Search size={16} style={{ position: "absolute", right: 12, top: 12, color: C.subtext }} />
        <input style={{ ...inputStyle, paddingRight: 36, maxWidth: 320 }} placeholder="ابحث عن مخدوم..." value={search} onChange={(e) => setSearch(e.target.value)} />
      </div>
      {members.length === 0 ? (
        <EmptyState icon={Users} title="لا يوجد مخدومون" subtitle="أضف مخدومين أولًا من صفحة المخدومين" action={<button onClick={() => setView("members")} style={btnPrimary}>الذهاب للمخدومين</button>} />
      ) : (
        <div style={{ background: C.card, borderRadius: 16, boxShadow: "0 2px 10px rgba(20,30,50,0.05)", overflow: "hidden" }}>
          {filteredMembers.map((m, idx) => {
            const status = pending[m.id];
            return (
              <div key={m.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", borderBottom: idx === filteredMembers.length - 1 ? "none" : `1px solid ${C.line}`, flexWrap: "wrap" }}>
                <Avatar name={m.name} photo={m.photoURL} size={42} />
                <div style={{ flex: 1, minWidth: 120, fontWeight: 700, fontSize: 14.5, color: C.ink }}>{m.name}</div>
                <div style={{ display: "flex", gap: 6 }}>
                  <StatusBtn active={status === "present"} color={C.sage} bg={C.sageSoft} icon={CheckCircle2} label="حاضر" onClick={() => setStatus(m.id, "present")} />
                  <StatusBtn active={status === "absent"} color={C.ember} bg={C.emberSoft} icon={XCircle} label="غائب" onClick={() => setStatus(m.id, "absent")} />
                  <StatusBtn active={status === "excused"} color={C.amber} bg={C.amberSoft} icon={Clock3} label="بعذر" onClick={() => setStatus(m.id, "excused")} />
                </div>
              </div>
            );
          })}
        </div>
      )}
      {members.length > 0 && (
        <div style={{ position: "sticky", bottom: 16, marginTop: 18, display: "flex", justifyContent: "center" }}>
          <button onClick={save} disabled={saving} style={{ ...btnGold, padding: "13px 34px", fontSize: 15, boxShadow: "0 10px 30px rgba(198,161,91,0.45)" }}><Save size={17} /> {saving ? "جارٍ الحفظ..." : "حفظ الحضور"}</button>
        </div>
      )}
    </div>
  );
}

/* ---------------- Reports ---------------- */

function ReportsPage({ members, meetings, attendance, setMobileOpen }) {
  const [tab, setTab] = useState("member");
  const [memberId, setMemberId] = useState(members[0]?.id || "");
  const [meetingId, setMeetingId] = useState(meetings[0]?.id || "");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  useEffect(() => { if (!memberId && members.length) setMemberId(members[0].id); }, [members]);
  useEffect(() => { if (!meetingId && meetings.length) setMeetingId(meetings[0].id); }, [meetings]);
  const tabs = [{ id: "member", label: "تقرير مخدوم" }, { id: "meeting", label: "تقرير اجتماع" }, { id: "period", label: "تقرير زمني" }];

  return (
    <div>
      <Topbar title="التقارير والإحصائيات" setMobileOpen={setMobileOpen} />
      <div style={{ display: "flex", gap: 8, marginBottom: 20, borderBottom: `1.5px solid ${C.line}` }}>
        {tabs.map((t) => <button key={t.id} onClick={() => setTab(t.id)} style={{ background: "none", border: "none", padding: "10px 4px", marginLeft: 20, fontWeight: 800, fontSize: 14, color: tab === t.id ? C.navy : C.subtext, borderBottom: tab === t.id ? `3px solid ${C.gold}` : "3px solid transparent", cursor: "pointer" }}>{t.label}</button>)}
      </div>
      {tab === "member" && (members.length === 0 ? <EmptyState icon={Users} title="لا يوجد مخدومون" subtitle="أضف مخدومين لعرض تقاريرهم" /> : (
        <>
          <div style={{ marginBottom: 16, maxWidth: 320 }}><select style={inputStyle} value={memberId} onChange={(e) => setMemberId(e.target.value)}>{members.map((m) => <option key={m.id} value={m.id}>{m.name}</option>)}</select></div>
          <MemberReportBody member={members.find((m) => m.id === memberId)} attendance={attendance} />
        </>
      ))}
      {tab === "meeting" && (meetings.length === 0 ? <EmptyState icon={Calendar} title="لا توجد اجتماعات" subtitle="أنشئ اجتماعًا لعرض تقريره" /> : (
        <>
          <div style={{ marginBottom: 16, maxWidth: 320 }}><select style={inputStyle} value={meetingId} onChange={(e) => setMeetingId(e.target.value)}>{meetings.map((m) => <option key={m.id} value={m.id}>{(m.title || "اجتماع") + " — " + fmtDateShort(m.date)}</option>)}</select></div>
          <MeetingReportBody meeting={meetings.find((m) => m.id === meetingId)} members={members} attendance={attendance} />
        </>
      ))}
      {tab === "period" && (
        <div>
          <div style={{ display: "flex", gap: 12, marginBottom: 18, flexWrap: "wrap" }}>
            <Field label="من تاريخ"><input style={inputStyle} type="date" value={from} onChange={(e) => setFrom(e.target.value)} /></Field>
            <Field label="إلى تاريخ"><input style={inputStyle} type="date" value={to} onChange={(e) => setTo(e.target.value)} /></Field>
          </div>
          <PeriodReportBody meetings={meetings} attendance={attendance} from={from} to={to} />
        </div>
      )}
    </div>
  );
}

function MemberReportBody({ member, attendance }) {
  if (!member) return null;
  const recs = attendance.filter((a) => a.memberId === member.id);
  const present = recs.filter((r) => r.status === "present").length;
  const absent = recs.filter((r) => r.status === "absent").length;
  const excused = recs.filter((r) => r.status === "excused").length;
  const rate = recs.length ? Math.round((present / recs.length) * 100) : 0;
  const data = [{ name: "حاضر", value: present, color: C.sage }, { name: "غائب", value: absent, color: C.ember }, { name: "بعذر", value: excused, color: C.amber }];
  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px,1fr))", gap: 14, marginBottom: 20 }}>
        <StatCard label="عدد الاجتماعات المسجّلة" value={recs.length} icon={Calendar} accent={C.navy} />
        <StatCard label="مرات الحضور" value={present} icon={CheckCircle2} accent={C.sage} />
        <StatCard label="مرات الغياب" value={absent} icon={XCircle} accent={C.ember} />
        <StatCard label="غياب بعذر" value={excused} icon={Clock3} accent={C.amber} />
        <StatCard label="نسبة الحضور" value={rate + "%"} icon={TrendingUp} accent={C.gold} />
      </div>
      {recs.length > 0 && (
        <div style={{ background: C.card, borderRadius: 16, padding: 20, boxShadow: "0 2px 10px rgba(20,30,50,0.05)", height: 280 }}>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart><Pie data={data} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={90} label={(e) => e.name + ": " + e.value}>{data.map((d, i) => <Cell key={i} fill={d.color} />)}</Pie><Tooltip /></PieChart>
          </ResponsiveContainer>
        </div>
      )}
    </div>
  );
}

function MeetingReportBody({ meeting, members, attendance }) {
  if (!meeting) return null;
  const recs = attendance.filter((a) => a.meetingId === meeting.id);
  const present = recs.filter((r) => r.status === "present").length;
  const absent = recs.filter((r) => r.status === "absent").length;
  const excused = recs.filter((r) => r.status === "excused").length;
  const rate = members.length ? Math.round((present / members.length) * 100) : 0;
  const data = [{ name: "حاضر", value: present, color: C.sage }, { name: "غائب", value: absent, color: C.ember }, { name: "بعذر", value: excused, color: C.amber }, { name: "لم يُسجَّل", value: Math.max(members.length - recs.length, 0), color: C.subtext }];
  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px,1fr))", gap: 14, marginBottom: 20 }}>
        <StatCard label="إجمالي المخدومين" value={members.length} icon={Users} accent={C.navy} />
        <StatCard label="الحاضرون" value={present} icon={CheckCircle2} accent={C.sage} />
        <StatCard label="الغائبون" value={absent} icon={XCircle} accent={C.ember} />
        <StatCard label="غياب بعذر" value={excused} icon={Clock3} accent={C.amber} />
        <StatCard label="نسبة الحضور" value={rate + "%"} icon={TrendingUp} accent={C.gold} />
      </div>
      <div style={{ background: C.card, borderRadius: 16, padding: 20, boxShadow: "0 2px 10px rgba(20,30,50,0.05)", height: 280 }}>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={data}><CartesianGrid strokeDasharray="3 3" stroke={C.line} /><XAxis dataKey="name" fontSize={13} /><YAxis allowDecimals={false} fontSize={12} /><Tooltip /><Bar dataKey="value" radius={[8, 8, 0, 0]}>{data.map((d, i) => <Cell key={i} fill={d.color} />)}</Bar></BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

function PeriodReportBody({ meetings, attendance, from, to }) {
  const inRange = meetings.filter((m) => { if (from && m.date < from) return false; if (to && m.date > to) return false; return true; }).sort((a, b) => new Date(a.date) - new Date(b.date));
  const chartData = inRange.map((m) => { const recs = attendance.filter((a) => a.meetingId === m.id); return { name: fmtDateShort(m.date), حاضر: recs.filter((r) => r.status === "present").length, غائب: recs.filter((r) => r.status === "absent").length, بعذر: recs.filter((r) => r.status === "excused").length }; });
  const totalRecs = attendance.filter((a) => inRange.some((m) => m.id === a.meetingId));
  const present = totalRecs.filter((r) => r.status === "present").length;
  const rate = totalRecs.length ? Math.round((present / totalRecs.length) * 100) : 0;
  if (inRange.length === 0) return <EmptyState icon={BarChart3} title="لا توجد اجتماعات في هذه الفترة" subtitle="اختر فترة زمنية تحتوي على اجتماعات" />;
  return (
    <div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(150px,1fr))", gap: 14, marginBottom: 20 }}>
        <StatCard label="عدد الاجتماعات" value={inRange.length} icon={Calendar} accent={C.navy} />
        <StatCard label="مرات الحضور" value={present} icon={CheckCircle2} accent={C.sage} />
        <StatCard label="مرات الغياب" value={totalRecs.filter((r) => r.status === "absent").length} icon={XCircle} accent={C.ember} />
        <StatCard label="نسبة الحضور" value={rate + "%"} icon={TrendingUp} accent={C.gold} />
      </div>
      <div style={{ background: C.card, borderRadius: 16, padding: 20, boxShadow: "0 2px 10px rgba(20,30,50,0.05)", height: 300 }}>
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={chartData}><CartesianGrid strokeDasharray="3 3" stroke={C.line} /><XAxis dataKey="name" fontSize={12} /><YAxis allowDecimals={false} fontSize={12} /><Tooltip /><Legend /><Line type="monotone" dataKey="حاضر" stroke={C.sage} strokeWidth={2.5} /><Line type="monotone" dataKey="غائب" stroke={C.ember} strokeWidth={2.5} /><Line type="monotone" dataKey="بعذر" stroke={C.amber} strokeWidth={2.5} /></LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

/* ---------------- Users management ---------------- */

function UsersPage({ users, currentUser, onChangeRole, toast, setMobileOpen }) {
  const [confirmChange, setConfirmChange] = useState(null);
  return (
    <div>
      <Topbar title="إدارة المستخدمين" subtitle={`${users.length} مستخدم`} setMobileOpen={setMobileOpen} />
      <div style={{ background: C.mist, borderRadius: 10, padding: "12px 16px", fontSize: 13, color: C.subtext, marginBottom: 16, lineHeight: 1.8 }}>
        الخدام بيسجّلوا حسابهم بنفسهم من شاشة "سجّل حساب جديد"، وإنت كمسؤول تقدر ترفّع أي حد لـ"مسؤول" أو تنزّله لـ"خادم" من هنا.
      </div>
      <div style={{ background: C.card, borderRadius: 16, boxShadow: "0 2px 10px rgba(20,30,50,0.05)", overflow: "hidden" }}>
        {users.map((u, idx) => (
          <div key={u.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "14px 18px", borderBottom: idx === users.length - 1 ? "none" : `1px solid ${C.line}` }}>
            <Avatar name={u.name} size={40} />
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 700, fontSize: 14.5, color: C.ink }}>{u.name}{u.id === currentUser.uid && <span style={{ color: C.subtext, fontWeight: 500 }}> (أنت)</span>}</div>
              <div style={{ fontSize: 12.5, color: C.subtext }}>{u.email}</div>
            </div>
            <span style={{ background: u.role === "admin" ? C.goldSoft : C.mist, color: u.role === "admin" ? C.amber : C.subtext, fontSize: 12, fontWeight: 700, padding: "4px 10px", borderRadius: 999 }}>{u.role === "admin" ? "مسؤول" : "خادم"}</span>
            {u.id !== currentUser.uid && (
              <button onClick={() => setConfirmChange(u)} style={btnGhost}>
                {u.role === "admin" ? "خفّضه لخادم" : "رفّعه لمسؤول"}
              </button>
            )}
          </div>
        ))}
      </div>
      <ConfirmDialog
        open={!!confirmChange}
        title="تغيير الصلاحية"
        message={confirmChange ? `هل تريد ${confirmChange.role === "admin" ? "تخفيض" : "ترقية"} "${confirmChange.name}" إلى ${confirmChange.role === "admin" ? "خادم" : "مسؤول"}؟` : ""}
        onCancel={() => setConfirmChange(null)}
        onConfirm={() => { onChangeRole(confirmChange.id, confirmChange.role === "admin" ? "servant" : "admin"); setConfirmChange(null); }}
      />
    </div>
  );
}

