/* ---------------- App ---------------- */

export default function App() {
  const [authLoading, setAuthLoading] = useState(true);
  const [authUser, setAuthUser] = useState(null);
  const [currentUser, setCurrentUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");

  const [members, setMembers] = useState([]);
  const [meetings, setMeetings] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [users, setUsers] = useState([]);
  const [dataLoading, setDataLoading] = useState(true);

  const [view, setView] = useState("dashboard");
  const [viewParams, setViewParams] = useState({});
  const [toasts, setToasts] = useState([]);
  const [mobileOpen, setMobileOpen] = useState(false);

  const toast = (message, type = "success") => {
    const id = uid();
    setToasts((t) => [...t, { id, message, type }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 3200);
  };

  // مراقبة حالة تسجيل الدخول
  useEffect(() => {
    const unsub = onAuthStateChanged(auth, async (u) => {
      setAuthUser(u);
      if (u) {
        try {
          const snap = await getDoc(doc(db, "users", u.uid));
          if (snap.exists()) setCurrentUser({ uid: u.uid, email: u.email, ...snap.data() });
          else setCurrentUser({ uid: u.uid, email: u.email, name: u.email, role: "servant" });
        } catch (e) {
          setCurrentUser({ uid: u.uid, email: u.email, name: u.email, role: "servant" });
        }
      } else {
        setCurrentUser(null);
      }
      setAuthLoading(false);
    });
    return () => unsub();
  }, []);

  // تحميل البيانات لحظيًا بعد تسجيل الدخول
  useEffect(() => {
    if (!authUser) { setMembers([]); setMeetings([]); setAttendance([]); setUsers([]); return; }
    setDataLoading(true);
    const unsub1 = onSnapshot(collection(db, "members"), (snap) => {
      setMembers(snap.docs.map((d) => {
        const data = d.data();
        return { id: d.id, ...data, createdAtMs: data.createdAt?.toMillis?.() || 0 };
      }));
    });
    const unsub2 = onSnapshot(collection(db, "meetings"), (snap) => setMeetings(snap.docs.map((d) => ({ id: d.id, ...d.data() }))));
    const unsub3 = onSnapshot(collection(db, "attendance"), (snap) => setAttendance(snap.docs.map((d) => ({ id: d.id, ...d.data() }))));
    const unsub4 = onSnapshot(collection(db, "users"), (snap) => setUsers(snap.docs.map((d) => ({ id: d.id, ...d.data() }))));
    setDataLoading(false);
    return () => { unsub1(); unsub2(); unsub3(); unsub4(); };
  }, [authUser]);

  /* ---- Auth actions ---- */
  const login = async (email, password) => { await signInWithEmailAndPassword(auth, email, password); toast("تم تسجيل الدخول بنجاح"); };
  const signup = async (email, password, name) => {
    const cred = await createUserWithEmailAndPassword(auth, email, password);
    const adminMetaSnap = await getDoc(doc(db, "meta", "adminExists"));
    const role = adminMetaSnap.exists() ? "servant" : "admin";
    await setDoc(doc(db, "users", cred.user.uid), { name, email, role, createdAt: serverTimestamp() });
    if (role === "admin") await setDoc(doc(db, "meta", "adminExists"), { createdAt: serverTimestamp() });
    toast(role === "admin" ? "تم إنشاء الحساب — إنت أول مسؤول للنظام" : "تم إنشاء الحساب بنجاح");
  };
  const logout = async () => { await signOut(auth); setView("dashboard"); };

  /* ---- Members ---- */
  // photoFile هنا هو نص base64 جاهز (من compressImage) بيتخزن مباشرة جوه المستند
  const addMember = async (data, photoFile) => {
    try {
      const photoURL = photoFile || null;
      await addDoc(collection(db, "members"), { ...data, photoURL, createdAt: serverTimestamp(), updatedAt: serverTimestamp() });
      toast("تمت إضافة المخدوم بنجاح");
    } catch (e) { toast("تعذر حفظ البيانات، حاول مرة أخرى", "error"); }
  };
  const updateMember = async (id, data, photoFile) => {
    try {
      const photoURL = photoFile || data.photoURL || null;
      await updateDoc(doc(db, "members", id), { ...data, photoURL, updatedAt: serverTimestamp() });
      toast("تم تحديث البيانات بنجاح");
    } catch (e) { toast("تعذر حفظ التعديلات", "error"); }
  };
  const deleteMember = async (id) => {
    try {
      const q = query(collection(db, "attendance"), where("memberId", "==", id));
      const snap = await getDocs(q);
      const batch = writeBatch(db);
      snap.docs.forEach((d) => batch.delete(d.ref));
      batch.delete(doc(db, "members", id));
      await batch.commit();
      toast("تم حذف المخدوم");
    } catch (e) { toast("حدث خطأ أثناء الحذف", "error"); }
  };

  /* ---- Meetings ---- */
  const addMeeting = async (data) => {
    try { await addDoc(collection(db, "meetings"), { ...data, createdAt: serverTimestamp() }); toast("تم إنشاء الاجتماع بنجاح"); }
    catch (e) { toast("تعذر حفظ الاجتماع", "error"); }
  };
  const updateMeeting = async (id, data) => {
    try { await updateDoc(doc(db, "meetings", id), data); toast("تم تحديث الاجتماع"); }
    catch (e) { toast("تعذر حفظ التعديلات", "error"); }
  };
  const deleteMeeting = async (id) => {
    try {
      const q = query(collection(db, "attendance"), where("meetingId", "==", id));
      const snap = await getDocs(q);
      const batch = writeBatch(db);
      snap.docs.forEach((d) => batch.delete(d.ref));
      batch.delete(doc(db, "meetings", id));
      await batch.commit();
      toast("تم حذف الاجتماع");
    } catch (e) { toast("حدث خطأ أثناء الحذف", "error"); }
  };

  /* ---- Attendance (معرف مستند ثابت meetingId_memberId يمنع التكرار) ---- */
  const saveAttendance = async (meetingId, pendingMap, byUser) => {
    try {
      const batch = writeBatch(db);
      Object.entries(pendingMap).forEach(([memberId, status]) => {
        if (!status) return;
        const recId = `${meetingId}_${memberId}`;
        batch.set(doc(db, "attendance", recId), { memberId, meetingId, status, recordedAt: serverTimestamp(), recordedBy: byUser?.name || "—" }, { merge: true });
      });
      await batch.commit();
      toast("تم حفظ الحضور بنجاح");
    } catch (e) { toast("تعذر حفظ الحضور، حاول مرة أخرى", "error"); }
  };

  /* ---- Users ---- */
  const changeUserRole = async (targetUid, newRole) => {
    try { await updateDoc(doc(db, "users", targetUid), { role: newRole }); toast("تم تحديث صلاحية المستخدم"); }
    catch (e) { toast("تعذر تحديث الصلاحية", "error"); }
  };

  if (authLoading) {
    return (
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: C.mist }}>
        <div style={{ textAlign: "center" }}><img src={LOGO_SRC} style={{ width: 70, borderRadius: 12, marginBottom: 14, opacity: 0.9 }} alt="" /><div style={{ color: C.navy, fontWeight: 700 }}>جارٍ التحميل...</div></div>
      </div>
    );
  }
  if (!authUser || !currentUser) return <AuthScreen mode={authMode} setMode={setAuthMode} onLogin={login} onSignup={signup} toast={toast} />;

  const isAdmin = currentUser.role === "admin";

  return (
    <div dir="rtl" style={{ fontFamily: "'Cairo', system-ui, sans-serif", background: C.mist, minHeight: "100vh" }}>
      <style>{`
        * { box-sizing: border-box; }
        input:focus, select:focus, textarea:focus { border-color: ${C.gold} !important; }
        @media (max-width: 880px) {
          .sidebar-el { transform: translateX(100%); }
          .mobile-menu-btn { display: flex !important; }
          .main-content { margin-right: 0 !important; }
          .dash-grid { grid-template-columns: 1fr !important; }
        }
      `}</style>

      <Sidebar view={view} setView={setView} currentUser={currentUser} onLogout={logout} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} />

      <main className="main-content" style={{ marginRight: 240, padding: "24px 28px 60px", minHeight: "100vh" }}>
        {view === "dashboard" && (<><Topbar title="الرئيسية" subtitle={`مرحبًا، ${currentUser.name}`} setMobileOpen={setMobileOpen} /><Dashboard members={members} meetings={meetings} attendance={attendance} setView={setView} setViewParams={setViewParams} /></>)}
        {view === "members" && <MembersPage members={members} attendance={attendance} onAdd={addMember} onUpdate={updateMember} onDelete={deleteMember} openParams={viewParams} setView={setView} setViewParams={setViewParams} isAdmin={isAdmin} toast={toast} setMobileOpen={setMobileOpen} />}
        {view === "memberProfile" && <MemberProfile member={members.find((m) => m.id === viewParams.memberId)} attendance={attendance} meetings={meetings} setView={setView} />}
        {view === "meetings" && <MeetingsPage meetings={meetings} attendance={attendance} onAdd={addMeeting} onUpdate={updateMeeting} onDelete={deleteMeeting} openParams={viewParams} setView={setView} setViewParams={setViewParams} isAdmin={isAdmin} toast={toast} setMobileOpen={setMobileOpen} />}
        {view === "attendance" && <AttendancePage meeting={meetings.find((m) => m.id === viewParams.meetingId)} members={members} attendance={attendance} currentUser={currentUser} onSaveAttendance={saveAttendance} setView={setView} />}
        {view === "reports" && <ReportsPage members={members} meetings={meetings} attendance={attendance} setMobileOpen={setMobileOpen} />}
        {view === "users" && isAdmin && <UsersPage users={users} currentUser={currentUser} onChangeRole={changeUserRole} toast={toast} setMobileOpen={setMobileOpen} />}
        {view === "settings" && <SettingsPage members={members} meetings={meetings} attendance={attendance} setMobileOpen={setMobileOpen} />}
      </main>

      <Toasts toasts={toasts} remove={(id) => setToasts((t) => t.filter((x) => x.id !== id))} />
    </div>
  );
}
